CREATE TABLE IF NOT EXISTS workspaces (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,description TEXT NOT NULL,owner_id BIGINT NOT NULL,created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS members (workspace_id BIGINT NOT NULL,user_id BIGINT NOT NULL,role VARCHAR(20) NOT NULL,created_at VARCHAR(40) NOT NULL,PRIMARY KEY(workspace_id,user_id),FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS invitations (id BIGINT AUTO_INCREMENT PRIMARY KEY,workspace_id BIGINT NOT NULL,email VARCHAR(254) NOT NULL,role VARCHAR(20) NOT NULL,created_at VARCHAR(40) NOT NULL,UNIQUE(workspace_id,email),FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS outbox (id BIGINT AUTO_INCREMENT PRIMARY KEY,event_id VARCHAR(64) NOT NULL UNIQUE,user_id BIGINT NOT NULL,title VARCHAR(200) NOT NULL,message VARCHAR(500) NOT NULL,link VARCHAR(200) NOT NULL);
